pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 calls, uint256 seed) public {
        uint256 totalTickets = 0;
        uint256 totalPayouts = 0;
        uint256 totalFees = 0;

        vm.assume(calls > 0 && calls <= 10);

        for (uint256 i = 0; i < calls; i++) {
            vm.deal(address(this), 10 ether);
            uint256 potBefore = c.pot();

            // Simulate the random outcome deterministically
            uint256 pseudoRandom = uint256(keccak256(abi.encodePacked(seed, i))) % 2;

            // Prepare call with the correct amount
            c.play{value: 10 ether}();

            uint256 potAfter = c.pot();

            totalTickets += 10 ether;

            if (pseudoRandom == 0) {
                // Win case: player gets pot after fee deducted, pot reset to 0
                totalPayouts += potBefore + 10 ether - 1 ether;
                totalFees += 1 ether;
            }
        }

        uint256 expectedPot = totalTickets - totalPayouts - totalFees;
        assertTrue(c.pot() == expectedPot);
    }
}

