pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed) public {
        // Bound seed to avoid overflow issues
        seed = bound(seed, 0, type(uint256).max);

        // Get initial pot and balance
        uint256 initialPot = c.pot();
        uint256 initialBalance = address(c).balance;

        // Simulate a call to play with exactly TICKET_AMOUNT (10) wei
        // We need to send exactly 10 wei; use vm.deal to give the caller funds
        address caller = address(uint160(seed + 1)); // some unique caller
        vm.deal(caller, 10);

        // Wrap in try/catch to handle any revert (e.g. if caller has insufficient funds)
        bool reverted;
        try c.play{value: 10}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read final state
        uint256 finalPot = c.pot();
        uint256 finalBalance = address(c).balance;

        // The general rule: 
        // If the call reverted, no state changes occurred (pot and balance unchanged)
        // If the call succeeded, either:
        //   - random == 0 (win): pot becomes 0, balance becomes FEE_AMOUNT (1) transferred to bank
        //   - random != 0 (lose): pot increases by 10 (the ticket amount), balance also increases by 10
        // But we cannot know the random outcome, so we check invariants:
        // - pot is always either 0 or initialPot + 10 (since we add 10 on every call)
        // - balance is always either pot + fee (if pot>0? No, simpler: balance is either finalPot or finalPot + 1? Actually, when win, pot=0, balance=1; when lose, pot=initialPot+10, balance=initialPot+10)
        // So we can assert: (finalPot == 0 && finalBalance == 1) || (finalPot == initialPot + 10 && finalBalance == finalPot)

        bool invariant1 = (finalPot == 0 && finalBalance == 1 && !reverted);
        bool invariant2 = (finalPot == initialPot + 10 && finalBalance == finalPot && !reverted);
        bool invariantRevert = (reverted && finalPot == initialPot && finalBalance == initialBalance);

        assertTrue(invariant1 || invariant2 || invariantRevert);
    }
}

