import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address player, uint seed) public {
        vm.assume(player != address(0) && player != address(c.bank()));
        vm.deal(player, 10 ether);

        uint initialBankBalance = address(c.bank()).balance;
        uint initialContractBalance = address(c).balance;

        vm.prank(player);
        (bool success, ) = address(c).call{value: 10}(abi.encodeWithSignature("play()"));

        uint bankFeeChange = address(c.bank()).balance - initialBankBalance;
        uint contractBalanceChange = address(c).balance - initialContractBalance;

        // The total ETH accounted for (contract balance + bank fees + player's gain) equals the ticket amount
        // If play succeeded, the contract either paid out pot - fee to player and fee to bank, or kept everything.
        // Net change: contract balance change + bank fee change = 10 (if no payout) or = 0 (if payout, because pot goes to player and fee to bank, contract ends with 0)
        // Actually the rule is: After play(), the sum of contract balance and bank balance increase equals 10 (the ticket) minus any amount transferred to player
        // But player's balance is not observable, so we use the fact that pot + bank's fee = ticket value at time of play.
        // For the reference: pot starts at 0, then becomes 10. If random==0, pot becomes 0, bank gets 1, player gets 9. Net changes: contract -10, bank +1, so sum = -9, player +9, total sum = 0. If random!=0, pot stays 10, bank unchanged, contract balance stays 10. Net: contract +10, bank 0, sum = +10.
        // So the rule is: contractBalanceChange + bankFeeChange == 10 || contractBalanceChange + bankFeeChange == 0
        assertTrue(contractBalanceChange + bankFeeChange == 10 || contractBalanceChange + bankFeeChange == 0);
    }
}

