pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed) public {
        // Bound the seed to a reasonable range
        seed = bound(seed, 0, type(uint64).max);
        // Manipulate block.timestamp and block.difficulty to control randomness
        vm.warp(seed);
        vm.difficulty(seed + 1);

        // Fund the contract
        address(c).call{value: 100 ether}("");
        uint256 initialBankBalance = address(c.bank()).balance;
        uint256 initialPot = c.pot();

        // Call play() with exactly TICKET_AMOUNT
        (bool success,) = address(c).call{value: 10 ether}(abi.encodeWithSignature("play()"));

        if (success) {
            // The random result depends on the manipulated values; we can compute it
            uint256 random = uint256(keccak256(abi.encodePacked(seed, seed + 1))) % 2;
            if (random == 0) {
                // Player won: pot should be 0, bank should have received FEE_AMOUNT
                assertTrue(c.pot() == 0, "Pot not reset after win");
                assertTrue(address(c.bank()).balance == initialBankBalance + 1 ether, "Bank fee not correct");
            } else {
                // Player lost: pot should have increased by TICKET_AMOUNT
                assertTrue(c.pot() == initialPot + 10 ether, "Pot not increased on loss");
            }
        }
    }
}

