pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property() public {
        // Record the balance of the contract before play
        uint256 balanceBefore = address(c).balance;

        // Send exactly TICKET_AMOUNT wei to play
        vm.deal(address(this), 10 ether);
        (bool success, ) = address(c).call{value: 10 wei}(abi.encodeWithSignature("play()"));

        // If the call succeeded (i.e., msg.value == TICKET_AMOUNT satisfied)
        if (success) {
            // The pot should equal (balanceBefore - 1) because if the game is won, the bank takes 1 wei fee.
            // But the invariant is: pot + (1 if random == 0 else 0) == balanceBefore + 10 - (pot_changed after win?)
            // Wait, easier: After play(), pot + (bank's fee if won) = total sent since last win.
            // Actually, we can use: pot should equal (total sent - (bank's fee if won)).
            // But we cannot know if won, so we must verify a rule that holds in both cases.

            // The correct invariant: pot == balanceBefore + 10 wei - (FEE_AMOUNT if random == 0 else 0).
            // But we cannot observe random directly. However, we can assert that:
            // pot is always either balanceBefore + 10 (if not won) or balanceBefore + 10 - 1 (if won).
            // So pot must be in {balanceBefore + 9, balanceBefore + 10}.
            uint256 pot = c.pot();
            assertTrue(pot == balanceBefore + 9 || pot == balanceBefore + 10);
        }
    }
}

